import { type DocumentState, ControlledDocumentState } from '@hcengineering/controlled-documents'
import { combine } from 'effector'
import { $isLatestVersion, $controlledDocument, $documentState } from './editor'

const statesForSnapshotCreation: Array<DocumentState | ControlledDocumentState> = [
  ControlledDocumentState.Reviewed,
  ControlledDocumentState.Approved,
  ControlledDocumentState.Rejected
]

export const $canCreateNewSnapshot = combine(
  $isLatestVersion,
  $controlledDocument,
  $documentState,
  (latest, document, state) => {
    return document !== null && state != null && latest && statesForSnapshotCreation.includes(state)
  }
)
